  await home(p);await workUnit(p,5.6);await assets(p);await workUnit(p,.8);await p.waitForTimeout(150);const started=(Date.now()-epoch)/1000;
  const animate=async(from,to,duration)=>p.evaluate(async({from,to,duration})=>{const root=document.querySelector('[data-home-work-journey]'),top=scrollY+root.getBoundingClientRect().top,height=innerHeight,start=performance.now();await new Promise(resolve=>{function next(now){const t=Math.min(1,(now-start)/duration);scrollTo({top:top+(from+(to-from)*t)*height,behavior:'instant'});if(t<1)requestAnimationFrame(next);else requestAnimationFrame(resolve)}requestAnimationFrame(next)})},{from,to,duration});
  await animate(.8,6.15,6500);await p.waitForTimeout(350);await animate(6.15,.8,4500);await p.waitForTimeout(250);const duration=(Date.now()-epoch)/1000-started,video=p.video();await c.close();const raw=await video.path(),file=label+'-continuous-scroll.webm',destination=path.join(out,file),probe=spawnSync('ffprobe',['-v','error','-show_entries','format=duration','-of','default=noprint_wrappers=1:nokey=1',raw],{maxBuffer:1024*1024});if(probe.status!==0)throw Error('Video duration probe failed');const rawDuration=Number(probe.stdout.toString().trim()),trimStart=Math.max(0,rawDuration-duration);
  const result=spawnSync('ffmpeg',['-y','-loglevel','error','-ss',String(trimStart),'-i',raw,'-t',String(duration),'-an','-c:v','libvpx-vp9','-crf','35','-b:v','0',destination],{maxBuffer:1024*1024,timeout:120000});if(result.status!==0)throw Error('Video trim failed: '+result.stderr.toString());
